/**
 * Вернуть иконку. $class добавляется к svg, размер задаётся через CSS.
 */
function icon(string $name, string $class = '', string $title = ''): string
{
    if (! isset(ICON_PATHS[$name])) {
        return '';
    }

    $attrs = 'class="ic' . ($class !== '' ? ' ' . e($class) : '') . '"';
    $label = $title !== ''
        ? ' role="img" aria-label="' . e($title) . '"'
        : ' aria-hidden="true"';

    return '<svg ' . $attrs . ' viewBox="0 0 300 300" xmlns="http://www.w3.org/2000/svg"' . $label . '>'
        . '<g transform="translate(0,300) scale(1,-1)">'
        . '<path fill="currentColor" d="' . ICON_PATHS[$name] . '"/>'
        . '</g></svg>';
}